class MyDataSource54 implements IDataSource {
  private list: number[] = []

  constructor(list: number[]) {
    this.list = list
  }

  totalCount(): number {
    return this.list.length
  }

  getData(index: number): number {
    return this.list[index]
  }

  registerDataChangeListener(listener: DataChangeListener): void {
  }

  unregisterDataChangeListener() {
  }
}
@Reusable
@Component
struct SwiperItemComponent54 {
  @State item: string = ''

  aboutToReuse(params: Record<string, ESObject>) {
    this.item = params.item
  }

  build() {
    Text(this.item)
      .width('100%')
      .height('100%')
      .backgroundColor(0xAFEEEE)
      .textAlign(TextAlign.Center)
      .borderColor(Color.Red)
      .borderWidth(0)
      .fontSize(30)
  }
}

@Entry
@Component
struct SwiperNextPrevMarginExample54 {
  private swiperController: SwiperController = new SwiperController()
  private data: MyDataSource54 = new MyDataSource54([])

  aboutToAppear(): void {
    let list: number[] = []
    for (let i = 1; i <= 10; i++) {
      list.push(i);
    }
    this.data = new MyDataSource54(list)
  }

  build() {
    Column({ space: 5 }) {
      Swiper(this.swiperController) {
        LazyForEach(this.data, (item: string,index:number) => {
          SwiperItemComponent54({
            item: item
          }).reuseId(index + "")
        }, (item: string) => item)
      }
      .cachedCount(2)
      .index(1)
      .autoPlay(false)
      .interval(4000)
      .nextMargin(15)
      .vertical(true)

      .prevMargin(6)
      .displayCount(1)
      .borderWidth(0)
      .width(250)
      .height(400)
       .displayMode(SwiperDisplayMode.STRETCH)
      .loop(true)
      .duration(1000)
      .itemSpace(0)
      .key("swiperNextPrevMargin54")

      Row({ space: 12 }) {
        Button('showNext')
          .onClick(() => {
            this.swiperController.showNext()
          })
        Button('showPrevious')
          .onClick(() => {
            this.swiperController.showPrevious()
          })
      }.margin(5)
    }.width('100%')
    .margin({ top: 5 }).key('ColumnSwiper54')
  }
}

